from pathlib import Path
p=Path('web/globe3d.js');s=p.read_text(encoding='utf-8');needle="document.getElementById('globe-clear').onclick=()=>{active=[];update()};";rep=needle+"document.getElementById('globe-amap').onclick=showAmap;";s=s.replace(needle,rep);s += "\nfunction showAmap(){const info=byId('amap-info');info.hidden=false;info.textContent='高德 3D 需要配置 API Key。请在页面控制台设置 window.AMAP_KEY 后再次点击。';if(!window.AMAP_KEY)return;if(window.AMap){mountAmap();return}const sc=document.createElement('script');sc.src='https://webapi.amap.com/maps?v=2.0&key='+encodeURIComponent(window.AMAP_KEY);sc.onload=mountAmap;sc.onerror=()=>info.textContent='高德 JS API 加载失败，请检查 Key、域名白名单或网络。';document.head.appendChild(sc)}\nfunction mountAmap(){const host=byId('globe-viz');host.innerHTML='';const map=new AMap.Map(host,{zoom:4,center:[105,35],viewMode:'3D',pitch:48,showBuildingBlock:true,terrain:true});const layer=new AMap.Object3DLayer();map.add(layer);active.forEach(n=>{const d=C.find(x=>x[0]===n);if(!d)return;const m=new AMap.Marker({position:[d[1],d[2]],title:n});m.setMap(map)});byId('amap-info').textContent='高德 3D 地形模式 · 已显示当前环线城市；返回全球视角请刷新页面。'}\n";p.write_text(s,encoding='utf-8')
